"""
Step 2: Recipe Modification

This module applies structured modifications to recipes using search-and-replace operations.
It takes ModificationObject instances and applies their edits to recipe ingredients and instructions.

Edits are applied conservatively: a target must be found unambiguously, a tweak's
edits are applied all-or-nothing, and an edit never silently overwrites a change
made by a different review. Every refusal is reported as an EditError so it can be
recorded rather than lost.
"""

import copy
import re
from dataclasses import dataclass, field
from difflib import SequenceMatcher
from typing import Dict, List, Optional, Set, Tuple

from loguru import logger

from .models import ChangeRecord, ModificationEdit, ModificationObject, Recipe

# An instruction step is only removed when the find text covers most of it;
# otherwise a short find (e.g. "walnuts") would delete a whole step.
MIN_INSTRUCTION_REMOVE_COVERAGE = 0.6


class EditError(Exception):
    """An edit that could not be applied safely."""

    def __init__(self, reason: str, detail: str):
        super().__init__(f"{reason}: {detail}")
        self.reason = reason  # not_found | ambiguous | conflict | no_op | invalid
        self.detail = detail


@dataclass
class _Line:
    """A recipe line with its provenance."""

    text: str
    origin: Optional[int]  # index in the original recipe list; None if added
    touched_by: Set[str] = field(default_factory=set)  # owners that changed it


@dataclass
class _State:
    """Working copy of a recipe being modified."""

    lines: Dict[str, List[_Line]]  # keyed by edit target
    original: Dict[str, List[str]]
    removed_by: Dict[Tuple[str, int], str] = field(default_factory=dict)


@dataclass
class ModificationResult:
    """Outcome of applying one modification."""

    modification: ModificationObject
    owner: str
    changes: List[ChangeRecord]
    error: Optional[EditError] = None

    @property
    def applied(self) -> bool:
        return self.error is None


def _loose_pattern(text: str) -> str:
    """Regex matching text case-insensitively with flexible whitespace."""
    return r"\s+".join(re.escape(token) for token in text.split())


class RecipeModifier:
    """Applies structured modifications to recipes using search-and-replace operations."""

    def __init__(self, similarity_threshold: float = 0.85):
        """
        Initialize the RecipeModifier.

        Args:
            similarity_threshold: Minimum whole-line similarity for the fuzzy
                fallback, used only when the find text is not a substring of any line
        """
        self.similarity_threshold = similarity_threshold
        logger.info(f"Initialized RecipeModifier with similarity threshold: {similarity_threshold}")

    def _search(self, find: str, texts: List[str]) -> Tuple[str, List[int]]:
        """Return the first match method that hits, and the indices it hits."""
        for method, pattern, flags in (
            ("exact", re.escape(find), 0),
            ("normalized", _loose_pattern(find), re.IGNORECASE),
        ):
            hits = [i for i, t in enumerate(texts) if re.search(pattern, t, flags)]
            if hits:
                return method, hits
        return "", []

    def find_best_match(
        self, edit: ModificationEdit, lines: List[_Line]
    ) -> Tuple[int, str, float]:
        """
        Locate the line an edit targets.

        Tries an exact substring, then a case/whitespace-insensitive substring, then
        a whole-line fuzzy match. Several hits are resolved only by the edit's
        line_index (which refers to the original recipe numbering).

        Args:
            edit: Edit whose find text to locate
            lines: Current lines of the edit's target list

        Returns:
            Tuple of (line position, match method, similarity score)

        Raises:
            EditError: If the target is missing or ambiguous
        """
        find = edit.find.strip()
        texts = [line.text for line in lines]

        method, hits = self._search(find, texts)
        if hits:
            if len(hits) == 1:
                return hits[0], method, 1.0
            hinted = [i for i in hits if lines[i].origin == edit.line_index]
            if len(hinted) == 1:
                return hinted[0], method, 1.0
            raise EditError(
                "ambiguous",
                f"'{find}' matches {len(hits)} {edit.target} lines and line_index "
                f"{edit.line_index} does not single one out",
            )

        scores = sorted(
            (
                (SequenceMatcher(None, find.lower(), t.lower()).ratio(), i)
                for i, t in enumerate(texts)
            ),
            reverse=True,
        )
        if scores and scores[0][0] >= self.similarity_threshold:
            score, index = scores[0]
            if len(scores) > 1 and scores[1][0] >= self.similarity_threshold:
                raise EditError(
                    "ambiguous", f"'{find}' is similar to several {edit.target} lines"
                )
            return index, "fuzzy", score

        best = scores[0][0] if scores else 0.0
        raise EditError(
            "not_found", f"'{find}' not found in {edit.target} (best similarity {best:.2f})"
        )

    def _explain_missing(self, edit: ModificationEdit, state: _State) -> EditError:
        """Turn a miss into a conflict when an earlier change removed the target."""
        error = None
        try:
            self.find_best_match(edit, state.lines[edit.target])
        except EditError as e:
            error = e
        if error is None or error.reason != "not_found":
            return error

        original = state.original[edit.target]
        _, hits = self._search(edit.find.strip(), original)
        for origin in hits:
            owners = set(state.removed_by.get((edit.target, origin), "").split()) or {
                owner
                for line in state.lines[edit.target]
                if line.origin == origin
                for owner in line.touched_by
            }
            if owners:
                return EditError(
                    "conflict",
                    f"'{edit.find}' was already changed by {', '.join(sorted(owners))}",
                )
        return error

    def _check_conflict(self, edit: ModificationEdit, line: _Line, owner: str) -> None:
        """Refuse to edit an ingredient another review already changed."""
        others = line.touched_by - {owner}
        # An ingredient line is one amount of one thing, so two reviews changing it
        # compete. Instruction steps hold many details; a different review may edit
        # them as long as its find text is still there.
        if others and edit.target == "ingredients":
            raise EditError(
                "conflict",
                f"ingredient '{line.text}' was already changed by {', '.join(sorted(others))}",
            )

    def _validate(self, edit: ModificationEdit) -> None:
        if not edit.find.strip():
            raise EditError("invalid", "edit has no find text")
        if edit.operation == "replace" and edit.replace is None:
            raise EditError("invalid", f"replace of '{edit.find}' has no replacement text")
        if edit.operation == "add_after" and not (edit.add or "").strip():
            raise EditError("invalid", f"add_after '{edit.find}' has no text to add")

    def _apply_located(
        self, edit: ModificationEdit, line: _Line, method: str, score: float,
        state: _State, owner: str,
    ) -> ChangeRecord:
        """Apply one edit to an already-located line object."""
        lines = state.lines[edit.target]
        change_type = "ingredient" if edit.target == "ingredients" else "instruction"
        position = next((i for i, x in enumerate(lines) if x is line), None)
        if position is None:
            raise EditError("conflict", f"'{edit.find}' was removed by another edit of this tweak")

        if edit.operation == "replace":
            original_text = line.text
            if method == "fuzzy":
                new_text = edit.replace
            else:
                pattern = re.escape(edit.find.strip()) if method == "exact" else _loose_pattern(edit.find)
                flags = 0 if method == "exact" else re.IGNORECASE
                matches = list(re.finditer(pattern, original_text, flags))
                if not matches:
                    raise EditError("conflict", f"'{edit.find}' was changed by another edit of this tweak")
                if len(matches) > 1:
                    raise EditError("ambiguous", f"'{edit.find}' occurs {len(matches)} times in '{original_text}'")
                start, end = matches[0].span()
                new_text = original_text[:start] + edit.replace + original_text[end:]
            new_text = re.sub(r"\s{2,}", " ", new_text).strip()
            if new_text == original_text:
                raise EditError("no_op", f"replacing '{edit.find}' leaves the line unchanged")
            if not new_text:
                raise EditError("invalid", f"replace would empty '{original_text}'; use remove")
            line.text = new_text
            line.touched_by.add(owner)
            return ChangeRecord(
                type=change_type, from_text=original_text, to_text=new_text,
                operation="replace", line_ref=line.origin,
                match_method=method, match_score=round(score, 3),
            )

        if edit.operation == "add_after":
            new_line = _Line(text=edit.add.strip(), origin=None, touched_by={owner})
            lines.insert(position + 1, new_line)
            return ChangeRecord(
                type=change_type, from_text="", to_text=new_line.text,
                operation="add", line_ref=line.origin,
                match_method=method, match_score=round(score, 3),
            )

        # remove
        if edit.target == "instructions" and method != "fuzzy":
            coverage = len(edit.find.strip()) / max(len(line.text), 1)
            if coverage < MIN_INSTRUCTION_REMOVE_COVERAGE:
                raise EditError(
                    "invalid",
                    f"remove of '{edit.find}' would delete the whole step '{line.text}'; "
                    "a partial removal must be a replace",
                )
        lines.pop(position)
        if line.origin is not None:
            state.removed_by[(edit.target, line.origin)] = owner
        return ChangeRecord(
            type=change_type, from_text=line.text, to_text="",
            operation="remove", line_ref=line.origin,
            match_method=method, match_score=round(score, 3),
        )

    def _apply_to_state(
        self, state: _State, modification: ModificationObject, owner: str
    ) -> List[ChangeRecord]:
        """
        Apply every edit of a modification to the state, in place.

        All targets are located before anything changes, because the extractor
        writes every find against the original text. Raises EditError on the first
        edit that cannot be applied; the caller discards the partial state.
        """
        located = []
        for edit in modification.edits:
            self._validate(edit)
            try:
                position, method, score = self.find_best_match(edit, state.lines[edit.target])
            except EditError as e:
                raise self._explain_missing(edit, state) if e.reason == "not_found" else e
            line = state.lines[edit.target][position]
            self._check_conflict(edit, line, owner)
            located.append((edit, line, method, score))

        return [
            self._apply_located(edit, line, method, score, state, owner)
            for edit, line, method, score in located
        ]

    @staticmethod
    def _new_state(recipe: Recipe) -> _State:
        return _State(
            lines={
                "ingredients": [_Line(t, i) for i, t in enumerate(recipe.ingredients)],
                "instructions": [_Line(t, i) for i, t in enumerate(recipe.instructions)],
            },
            original={
                "ingredients": list(recipe.ingredients),
                "instructions": list(recipe.instructions),
            },
        )

    @staticmethod
    def _to_recipe(recipe: Recipe, state: _State) -> Recipe:
        return Recipe(
            recipe_id=f"{recipe.recipe_id}_modified",
            title=recipe.title,
            ingredients=[line.text for line in state.lines["ingredients"]],
            instructions=[line.text for line in state.lines["instructions"]],
            description=recipe.description,
            servings=recipe.servings,
            rating=recipe.rating,
        )

    def apply_modification(
        self,
        recipe: Recipe,
        modification: ModificationObject
    ) -> Tuple[Recipe, List[ChangeRecord]]:
        """
        Apply a complete modification to a recipe.

        Args:
            recipe: Original recipe to modify
            modification: Structured modification to apply

        Returns:
            Tuple of (modified_recipe, all_change_records)

        Raises:
            EditError: If any edit cannot be applied (the recipe is left unchanged)
        """
        state = self._new_state(recipe)
        changes = self._apply_to_state(state, modification, owner="modification")
        return self._to_recipe(recipe, state), changes

    def apply_modifications(
        self,
        recipe: Recipe,
        modifications: List[Tuple[str, ModificationObject]],
    ) -> Tuple[Recipe, List[ModificationResult]]:
        """
        Apply modifications in order, each all-or-nothing.

        Args:
            recipe: Original recipe to modify
            modifications: (owner, modification) pairs; the owner (e.g. a review id)
                decides what counts as a conflict between modifications

        Returns:
            Tuple of (final_modified_recipe, one ModificationResult per modification)
        """
        state = self._new_state(recipe)
        results = []

        logger.info(f"Applying {len(modifications)} modifications sequentially")

        for owner, modification in modifications:
            trial = copy.deepcopy(state)
            try:
                changes = self._apply_to_state(trial, modification, owner)
            except EditError as e:
                logger.warning(f"Skipped {modification.modification_type} from {owner}: {e}")
                results.append(ModificationResult(modification, owner, [], e))
                continue
            state = trial
            logger.info(f"Applied {modification.modification_type} from {owner}: {len(changes)} changes")
            results.append(ModificationResult(modification, owner, changes))

        final = self._to_recipe(recipe, state)
        logger.info(f"Applied all modifications. Final recipe has {len(final.ingredients)} ingredients and {len(final.instructions)} instructions")
        return final, results

