# An instruction step is only removed when the find text covers most of it;
# otherwise a short find (e.g. "walnuts") would delete a whole step.
MIN_INSTRUCTION_REMOVE_COVERAGE = 0.6


class EditError(Exception):
    """An edit that could not be applied safely."""

    def __init__(self, reason: str, detail: str):
        super().__init__(f"{reason}: {detail}")
        self.reason = reason  # not_found | ambiguous | conflict | no_op | invalid
        self.detail = detail


@dataclass
class _Line:
    """A recipe line with its provenance."""

    text: str
    origin: Optional[int]  # index in the original recipe list; None if added
    touched_by: Set[str] = field(default_factory=set)  # owners that changed it


@dataclass
class _State:
    """Working copy of a recipe being modified."""

    lines: Dict[str, List[_Line]]  # keyed by edit target
    original: Dict[str, List[str]]
    removed_by: Dict[Tuple[str, int], str] = field(default_factory=dict)


@dataclass
class ModificationResult:
    """Outcome of applying one modification."""

    modification: ModificationObject
    owner: str
    changes: List[ChangeRecord]
    error: Optional[EditError] = None

    @property
    def applied(self) -> bool:
        return self.error is None


