    def _search(self, find: str, texts: List[str]) -> Tuple[str, List[int]]:
        """Return the first match method that hits, and the indices it hits."""
        for method, pattern, flags in (
            ("exact", re.escape(find), 0),
            ("normalized", _loose_pattern(find), re.IGNORECASE),
