            hinted = [i for i in hits if lines[i].origin == edit.line_index]
            if len(hinted) == 1:
                return hinted[0], method, 1.0
            raise EditError(
                "ambiguous",
                f"'{find}' matches {len(hits)} {edit.target} lines and line_index "
                f"{edit.line_index} does not single one out",
            )

        scores = sorted(
            (
                (SequenceMatcher(None, find.lower(), t.lower()).ratio(), i)
