def _locate_original_anchor(
    self, edit: ModificationEdit, state: _State
) -> Optional[Tuple[int, str, float]]:
    """Find an add_after anchor by its original text, if that line still exists."""
    original = [_Line(text, i) for i, text in enumerate(state.original[edit.target])]
    try:
        index, method, score = self.find_best_match(edit, original)
    except EditError:
        return None
    lines = state.lines[edit.target]
    position = next((i for i, line in enumerate(lines) if line.origin == index), None)
    return None if position is None else (position, method, score)

def _check_conflict(self, edit: ModificationEdit, line: _Line, owner: str) -> None:
    """Refuse edits that would overwrite another review's change."""
    others = line.touched_by - {owner}
    # Inserting a new line next to a changed one overwrites nothing
    if not others or edit.operation == "add_after":
        return

